import urllib.request,re,concurrent.futures
urls=['https://law.nju.edu.cn/info/1051/26961.htm','https://law.nju.edu.cn/info/1051/27121.htm','https://yjsy.uibe.edu.cn/cms/infoArticleList.do?columnId=5235']
def work(u):
 try:
  s=urllib.request.urlopen(u,timeout=20).read().decode('utf-8','replace')
  print(u)
  for line in s.splitlines():
   if any(w in line for w in ['.pdf','2027年各招生','2027年招收推免','国际法学']): print(line[:1800])
 except Exception as e: print(u,str(e))
with concurrent.futures.ThreadPoolExecutor() as pool: list(pool.map(work,urls))
PY"

